}

public class Solution {
    public static void reverseInPlace(int[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            int temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
    }

    public static int[] reversedCopy(int[] arr) {
        int[] copy = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            copy[i] = arr[arr.length - 1 - i];
        }
        return copy;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 10};
        int[] copy = reversedCopy(numbers);
        System.out.println("Method called successfully");
        System.out.println("Returned value: " + copy[0]);
    }
}

public class Solution {
    public static long factorial(int n) {
        if (n < 0 || n > 20) {
            throw new IllegalArgumentException("Input must be between 0 and 20 to prevent overflow.");
        }
        if (n <= 1) {
            return 1L;
        }
        return n * factorial(n - 1);
    }

    public static void main(String[] args) {
        int input = 5;
        System.out.println("Input: " + input);
        System.out.println("Factorial: " + factorial(input));
    }
}

public class Solution {
