public class Solution {
    public static int binarySearch(int[] arr, int target, int low, int high) {
        if (low > high) {
            return -1; // Base case: element not found
        }
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] > target) {
            return binarySearch(arr, target, low, mid - 1);
        } else {
            return binarySearch(arr, target, mid + 1, high);
        }
    }

    public static void main(String[] args) {
        int[] sortedData = {2, 4, 6, 8, 10, 12, 14};
        int target = 10;
        int index = binarySearch(sortedData, target, 0, sortedData.length - 1);
        System.out.println("Method called successfully");
        System.out.println("Returned value: " + sortedData[index]);
    }
}

public class Solution {
    public static double power(double x, int n) {
        long exp = n;
        if (exp < 0) {
            x = 1.0 / x;
            exp = -exp;
        }
        return fastPow(x, exp);
    }

    private static double fastPow(double x, long n) {
        if (n == 0) return 1.0;
        double half = fastPow(x, n / 2);
        if (n % 2 == 0) {
            return half * half;
        } else {
            return x * half * half;
        }
    }

    public static void main(String[] args) {
        double result = power(2.0, 10);
        System.out.println("Method called successfully");
        System.out.println("Returned value: " + (int) result);
    }
}

import java.util.HashMap;
import java.util.Map;

public class Solution {
    private static final Map<Integer, Long> memo = new HashMap<>();

    public static long fib(int n) {
        if (n <= 0) return 0L;
        if (n == 1) return 1L;
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        long val = fib(n - 1) + fib(n - 2);
        memo.put(n, val);
        return val;
    }

    public static void main(String[] args) {
        System.out.print("First 7 Fibonacci numbers: ");
        for (int i = 0; i < 7; i++) {
            System.out.print(fib(i) + (i == 6 ? "" : " "));
        }
        System.out.println();
    }
}

