public class Solution {
    // Tail-recursive helper method
    public static long fibTail(int n, long a, long b) {
        if (n == 0) return a;
        if (n == 1) return b;
        return fibTail(n - 1, b, a + b);
    }

    // Iterative counterpart simulating tail-call stack reuse
    public static long fibIterative(int n) {
        if (n == 0) return 0;
        long a = 0, b = 1;
        for (int i = 2; i <= n; i++) {
            long next = a + b;
            a = b;
            b = next;
        }
        return b;
    }

    public static void main(String[] args) {
        System.out.print("First 7 Fibonacci numbers: ");
        for (int i = 0; i < 7; i++) {
            System.out.print(fibTail(i, 0, 1) + (i == 6 ? "" : " "));
        }
        System.out.println();
    }
}

import java.lang.reflect.Array;

public class Solution {
    @SuppressWarnings("unchecked")
    public static <T> T[] removeDuplicates(T[] array, Class<T> clazz) {
        if (array == null || array.length == 0) {
            return (T[]) Array.newInstance(clazz, 0);
        }
        T[] temp = (T[]) Array.newInstance(clazz, array.length);
        int uniqueCount = 0;

        for (T item : array) {
            boolean exists = false;
            for (int j = 0; j < uniqueCount; j++) {
                if (temp[j].equals(item)) {
                    exists = true;
                    break;
                }
            }
            if (!exists) {
                temp[uniqueCount++] = item;
            }
        }

        T[] result = (T[]) Array.newInstance(clazz, uniqueCount);
        System.arraycopy(temp, 0, result, 0, uniqueCount);
        return result;
    }

    public static void main(String[] args) {
        Integer[] data = {10, 20, 10, 30, 20};
        Integer[] unique = removeDuplicates(data, Integer.class);
        System.out.println("Method called successfully");
        System.out.println("Returned value: " + unique[0]);
    }
}

public class Solution {
    static class QueryBuilder {
        private String columns = "*";
        private String table;
        private String condition;

        public QueryBuilder select(String columns) {
            this.columns = columns;
            return this;
        }

        public QueryBuilder from(String table) {
            this.table = table;
            return this;
        }

        public QueryBuilder where(String condition) {
            this.condition = condition;
            return this;
        }

        public String build() {
            if (table == null || table.isEmpty()) {
                throw new IllegalStateException("FROM table clause is required");
            }
            StringBuilder query = new StringBuilder("SELECT ").append(columns).append(" FROM ").append(table);
            if (condition != null && !condition.isEmpty()) {
                query.append(" WHERE ").append(condition);
            }
            return query.toString();
        }
    }

    public static void main(String[] args) {
        String sql = new QueryBuilder()
                .select("id, name")
                .from("users")
                .where("status = 'ACTIVE'")
                .build();
        System.out.println("Generated SQL: " + sql);
    }
}

public class Solution {
    public static int knapsack(int[] weights, int[] values, int capacity) {
        Integer[][] memo = new Integer[weights.length][capacity + 1];
        return solve(weights, values, capacity, 0, memo);
    }

    private static int solve(int[] weights, int[] values, int capacity, int idx, Integer[][] memo) {
        if (idx >= weights.length || capacity <= 0) {
            return 0;
        }
        if (memo[idx][capacity] != null) {
            return memo[idx][capacity];
        }
        int exclude = solve(weights, values, capacity, idx + 1, memo);
        int include = 0;
        if (weights[idx] <= capacity) {
            include = values[idx] + solve(weights, values, capacity - weights[idx], idx + 1, memo);
        }
        return memo[idx][capacity] = Math.max(include, exclude);
    }

    public static void main(String[] args) {
        int[] weights = {2, 3, 4};
        int[] values = {3, 4, 7};
        int maxVal = knapsack(weights, values, 5);
        System.out.println("Method called successfully");
        System.out.println("Returned value: " + maxVal);
    }
}

import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<String> sanitizeTokens(String[] raw) {
        List<String> cleaned = new ArrayList<>();
        for (String s : raw) {
            if (s != null) cleaned.add(s.trim());
        }
        return cleaned;
    }

    public static List<Integer> parseNumbers(List<String> tokens) {
        List<Integer> numbers = new ArrayList<>();
        for (String t : tokens) {
            try {
                numbers.add(Integer.parseInt(t));
            } catch (NumberFormatException ignored) {}
        }
        return numbers;
    }

    public static List<Integer> filterPositive(List<Integer> numbers) {
        List<Integer> positives = new ArrayList<>();
        for (int n : numbers) {
            if (n > 0) positives.add(n);
        }
        return positives;
    }

    public static int summarize(List<Integer> numbers) {
        int sum = 0;
        for (int n : numbers) sum += n;
        return sum;
    }

    public static void main(String[] args) {
        String[] raw = {" 2 ", "-5", "8", "bad", " 0 "};
        int total = summarize(filterPositive(parseNumbers(sanitizeTokens(raw))));
        System.out.println("Method called successfully");
        System.out.println("Returned value: " + total);
    }
}
